//! A program's whole generated tree (`crates/game/src/generated/`, `crates/config/src/generated/`): one
//! module per object with events, one per script, the names the code refers to (`names.rs`), and the program
//! table (`program.rs`).

use std::collections::{BTreeMap, BTreeSet};
use std::fmt::Write as _;

use gm::Builtin;
use gmk::EventType;

use crate::emit::{PRELUDE, Symbols, emit_object, emit_unit, rid};
use crate::source::{Source, constant_value};

/// The first line of every generated file.
pub const HEADER: &str = "// @generated by crates/transpile from reference/spelunky_1_1_src.zip. Do not edit; run \
                          scripts/transpile.\n";

/// The generated files, by path relative to the output directory, and what they hold.
pub struct Output {
    pub files: BTreeMap<String, String>,
    pub units: usize,
    pub gml_lines: usize,
    pub rust_lines: usize,
    pub symbols: Symbols,
}

/// `gm::Event` for a `.gmk` event, as Rust source.
fn event_expr(event: &gmk::Event) -> String {
    let n = event.sub;
    let e = gm::Event::from_gm(event.event_type as u32, n as u32)
        .unwrap_or_else(|| panic!("unsupported event {:?} {n}", event.event_type));
    match e {
        gm::Event::Create => "Event::Create".into(),
        gm::Event::Destroy => "Event::Destroy".into(),
        gm::Event::Alarm(n) => format!("Event::Alarm({n})"),
        gm::Event::BeginStep => "Event::BeginStep".into(),
        gm::Event::Step => "Event::Step".into(),
        gm::Event::EndStep => "Event::EndStep".into(),
        gm::Event::Collision(o) => format!("Event::Collision(ObjectId({}))", o.0),
        gm::Event::Keyboard(k) => format!("Event::Keyboard({k})"),
        gm::Event::Mouse(k) => format!("Event::Mouse({k})"),
        gm::Event::Other(k) => format!("Event::Other({k})"),
        gm::Event::Draw => "Event::Draw".into(),
        gm::Event::KeyPress(k) => format!("Event::KeyPress({k})"),
        gm::Event::KeyRelease(k) => format!("Event::KeyRelease({k})"),
    }
}

/// Generates every file.
pub fn generate(src: &Source) -> Output {
    assert!(
        src.gmk.constants.is_empty(),
        "user-defined constants aren't supported"
    );
    // Unit names tell scripts (`scripts/<name>`) from object code (`<object>/<event>#<n>`).
    assert!(
        !src.parents.contains_key("scripts"),
        "an object named `scripts` would collide with the script units"
    );
    let mut files = BTreeMap::new();
    let mut syms = Symbols::default();

    // Objects with events: their code actions and event functions.
    let mut object_mods = String::new();
    for object in src.gmk.objects.iter().flatten() {
        if object.events.is_empty() {
            continue;
        }
        for event in &object.events {
            assert!(
                event.event_type != EventType::Trigger,
                "{}: trigger events aren't supported",
                object.name
            );
        }
        let code = emit_object(src, object, &mut syms);
        files.insert(
            format!("objects/{}.rs", object.name),
            format!("{HEADER}{PRELUDE}{code}"),
        );
        writeln!(object_mods, "pub mod {};", rid(&object.name)).unwrap();
    }
    files.insert(
        "objects/mod.rs".into(),
        format!("{HEADER}//! One module per object with events.\n\n{object_mods}"),
    );

    // Scripts, one module each, re-exported flat.
    let mut script_mods = String::new();
    for unit in src.units.iter().filter(|u| u.name.starts_with("scripts/")) {
        let name = &unit.name["scripts/".len()..];
        let code = emit_unit(src, &unit.name, name, &mut syms);
        files.insert(
            format!("scripts/{name}.rs"),
            format!("{HEADER}{PRELUDE}\n{code}"),
        );
        let r = rid(name);
        writeln!(script_mods, "mod {r};\npub use self::{r}::{r};").unwrap();
    }
    files.insert(
        "scripts/mod.rs".into(),
        format!(
            "{HEADER}//! Every script, as transpiled. Generated code calls them through `crate::scr`, where the \
             override table can replace some.\n\n{script_mods}"
        ),
    );

    files.insert("names.rs".into(), names(src, &syms));
    files.insert("program.rs".into(), program(src, &syms));
    files.insert(
        "mod.rs".into(),
        format!(
            "{HEADER}//! This program's GML, transpiled. See `docs/design/translation.md`.\n\n\
             #![allow(\n    non_snake_case,\n    non_upper_case_globals,\n    unused,\n    unreachable_code,\n    \
             clippy::all\n)]\n\
             // Except the ban on platform float functions (clippy.toml): game state must not come from them.\n\
             #![warn(clippy::disallowed_methods)]\n\n\
             pub mod names;\npub mod objects;\nmod program;\npub mod scripts;\n\n\
             pub use program::build_program;\n\n\
             /// The highest instance id placed in a room: `instance_create` numbers from the next one.\n\
             pub const LAST_INSTANCE_ID: i32 = {};\n\n\
             /// The game file's font slots, deleted ones included: `font_add_sprite` numbers from here.\n\
             pub const FONT_SLOTS: usize = {};\n",
            src.gmk.last_instance_id,
            src.gmk.fonts.len()
        ),
    );

    let rust_lines = files.values().map(|f| f.lines().count()).sum();
    Output {
        files,
        units: src.units.len(),
        gml_lines: src.units.iter().map(|u| u.source.lines().count()).sum(),
        rust_lines,
        symbols: syms,
    }
}

/// User variables (every referenced name that isn't a built-in), in id order.
fn user_vars(syms: &Symbols) -> Vec<&str> {
    syms.vars
        .iter()
        .map(String::as_str)
        .filter(|n| Builtin::from_name(n).is_none())
        .collect()
}

/// `(id, name)` of the resources that exist, by id.
fn resource_ids<T>(list: &[Option<T>], name: impl Fn(&T) -> &str) -> Vec<(usize, &str)> {
    list.iter()
        .enumerate()
        .filter_map(|(i, r)| Some((i, name(r.as_ref()?))))
        .collect()
}

fn names(src: &Source, syms: &Symbols) -> String {
    let mut out = format!(
        "{HEADER}//! Every name the generated code uses: variables, globals, resources, constants.\n\n\
         use gm::{{Builtin, FIRST_USER_VAR, GVar, Value, Var}};\n"
    );
    // Variables: built-ins have fixed ids; user variables are numbered by name from FIRST_USER_VAR.
    let user = user_vars(syms);
    out.push_str(
        "\n/// Instance variables and game-wide built-ins.\npub mod v {\n    use super::*;\n",
    );
    for name in &syms.vars {
        if let Some(b) = Builtin::from_name(name) {
            writeln!(
                out,
                "    pub const {}: Var = Builtin::{b:?}.var();",
                rid(name)
            )
            .unwrap();
        }
    }
    for (i, name) in user.iter().enumerate() {
        writeln!(
            out,
            "    pub const {}: Var = Var(FIRST_USER_VAR + {i});",
            rid(name)
        )
        .unwrap();
    }
    out.push_str("}\n");
    writeln!(
        out,
        "\n/// User variable names, by id from `FIRST_USER_VAR`.\npub const VAR_NAMES: [&str; {}] = [",
        user.len()
    )
    .unwrap();
    for name in &user {
        writeln!(out, "    {name:?},").unwrap();
    }
    out.push_str("];\n");

    out.push_str("\n/// `global.` and `globalvar` variables.\npub mod gv {\n    use super::*;\n");
    for (i, name) in syms.gvars.iter().enumerate() {
        writeln!(out, "    pub const {}: GVar = GVar({i});", rid(name)).unwrap();
    }
    out.push_str("}\n");
    writeln!(
        out,
        "\n/// Global variable names, by id.\npub const GLOBAL_NAMES: [&str; {}] = [",
        syms.gvars.len()
    )
    .unwrap();
    for name in &syms.gvars {
        writeln!(out, "    {name:?},").unwrap();
    }
    out.push_str("];\n");

    // Resources: their ids, as GML values.
    let g = &src.gmk;
    let modules = [
        ("obj", "Objects.", resource_ids(&g.objects, |o| &o.name)),
        ("spr", "Sprites.", resource_ids(&g.sprites, |s| &s.name)),
        ("rm", "Rooms.", resource_ids(&g.rooms, |r| &r.name)),
        (
            "bgr",
            "Backgrounds.",
            resource_ids(&g.backgrounds, |b| &b.name),
        ),
        (
            "scr_id",
            "Scripts, as values.",
            resource_ids(&g.scripts, |s| &s.name),
        ),
    ];
    for (module, doc, names) in modules {
        writeln!(out, "\n/// {doc}\npub mod {module} {{\n    use super::*;").unwrap();
        for (i, name) in names {
            writeln!(
                out,
                "    pub const {}: Value = Value::Real({i}.0);",
                rid(name)
            )
            .unwrap();
        }
        out.push_str("}\n");
    }

    out.push_str("\n/// The built-in constants the game uses.\npub mod k {\n    use super::*;\n");
    for name in &syms.constants {
        let v = constant_value(name).unwrap_or_else(|| {
            panic!("the constant `{name}` has no value in source::constant_value")
        });
        writeln!(out, "    pub const {name}: Value = Value::Real({v:?});").unwrap();
    }
    out.push_str("}\n");

    writeln!(
        out,
        "\n/// Each object's parent index as the game data stores it (-1 or -100 for none; -1 for missing \
         slots), for `object_get_parent`.\npub const PARENT_INDEX: [i32; {}] = [",
        g.objects.len()
    )
    .unwrap();
    for o in &g.objects {
        writeln!(out, "    {},", o.as_ref().map_or(-1, |o| o.parent)).unwrap();
    }
    out.push_str("];\n");

    let scripts = resource_ids(&g.scripts, |s| &s.name);
    writeln!(
        out,
        "\n/// Every script's name, for the override table's checks.\npub const SCRIPT_NAMES: [&str; {}] = [",
        scripts.len()
    )
    .unwrap();
    for (_, name) in &scripts {
        writeln!(out, "    {name:?},").unwrap();
    }
    out.push_str("];\n");
    out
}

fn program(src: &Source, syms: &Symbols) -> String {
    let g = &src.gmk;
    let mut out = format!(
        "{HEADER}//! The program table: objects, their events and variable layouts. `ProgramBuilder::build` derives \
         inheritance, holders and collision pairs.\n\n\
         use super::names::{{GLOBAL_NAMES, VAR_NAMES, v}};\nuse super::objects;\n\
         use gm::{{Event, EventFn, FIRST_USER_VAR, ObjectId, ObjectInfo, Program, ProgramBuilder, Var}};\n\n"
    );

    out.push_str(
        "/// Each object: id, name, parent (-1 for none), sprite, mask, solid, visible, persistent, depth.\n\
         const OBJECTS: &[(u32, &str, i32, i32, i32, bool, bool, bool, f64)] = &[\n",
    );
    for (i, o) in g.objects.iter().enumerate() {
        let Some(o) = o else { continue };
        writeln!(
            out,
            "    ({i}, {:?}, {}, {}, {}, {}, {}, {}, {:?}),",
            o.name,
            o.parent,
            o.sprite,
            o.mask,
            o.solid,
            o.visible,
            o.persistent,
            f64::from(o.depth)
        )
        .unwrap();
    }
    out.push_str("];\n\n");

    out.push_str("/// Each object's events, as each object defines them.\nconst EVENTS: &[(u32, Event, EventFn)] = &[\n");
    for (i, o) in g.objects.iter().enumerate() {
        let Some(o) = o else { continue };
        for event in &o.events {
            let ev = crate::source::event_name(g, event);
            writeln!(
                out,
                "    ({i}, {}, objects::{}::{ev}),",
                event_expr(event),
                rid(&o.name)
            )
            .unwrap();
        }
    }
    out.push_str("];\n\n");

    out.push_str(
        "/// The user variables each object's own code assigns (`build` adds its ancestors').\n\
         const LAYOUTS: &[(u32, &[Var])] = &[\n",
    );
    let layouts = crate::layout::layouts(src);
    let index: BTreeMap<&str, usize> = g
        .objects
        .iter()
        .enumerate()
        .filter_map(|(i, o)| Some((o.as_ref()?.name.as_str(), i)))
        .collect();
    for (object, vars) in &layouts {
        let known: BTreeSet<&String> = vars.iter().filter(|v| syms.vars.contains(*v)).collect();
        assert_eq!(
            known.len(),
            vars.len(),
            "{object}: layout names a variable no code uses"
        );
        let list: Vec<String> = vars.iter().map(|v| format!("v::{}", rid(v))).collect();
        writeln!(
            out,
            "    ({}, &[{}]),",
            index[object.as_str()],
            list.join(", ")
        )
        .unwrap();
    }
    out.push_str("];\n\n");

    out.push_str(
        "/// Builds the program. The game holds the result in a static; building is deterministic.\n\
         pub fn build_program() -> Program {\n    \
             let mut b = ProgramBuilder::new();\n    \
             for (i, name) in VAR_NAMES.iter().enumerate() {\n        \
                 let v = b.var(*name);\n        \
                 assert_eq!(v, Var(FIRST_USER_VAR + i as u16), \"user variables are numbered in order\");\n    \
             }\n    \
             for name in GLOBAL_NAMES {\n        \
                 b.global(name);\n    \
             }\n    \
             for &(id, name, parent, sprite, mask, solid, visible, persistent, depth) in OBJECTS {\n        \
                 let info = ObjectInfo {\n            \
                     name: name.into(),\n            \
                     parent: u32::try_from(parent).ok().map(ObjectId),\n            \
                     sprite,\n            \
                     mask,\n            \
                     solid,\n            \
                     visible,\n            \
                     persistent,\n            \
                     depth,\n        \
                 };\n        \
                 b.object(ObjectId(id), info);\n    \
             }\n    \
             for &(id, event, f) in EVENTS {\n        \
                 b.event(ObjectId(id), event, f);\n    \
             }\n    \
             for &(id, vars) in LAYOUTS {\n        \
                 b.layout(ObjectId(id), vars);\n    \
             }\n    \
             // The collision stage is gm's default, GM8's (`World::run_collisions`).\n    \
             b.build()\n\
         }\n",
    );
    out
}
